<?php
namespace App\Http\Controllers;
use App\Models\{Configuracion,Dispositivo,Renovacion};
use Illuminate\Http\Response;
class CartaCustodiaController extends Controller {
    public function desde_dispositivo(Dispositivo $dispositivo): Response {
        $dispositivo->load('empleado');
        return response($this->buildHtml($dispositivo->empleado,$dispositivo,'DSP-'.str_pad($dispositivo->id,4,'0',STR_PAD_LEFT),$dispositivo->fecha_asignacion?->isoFormat('D [de] MMMM [de] YYYY')??now()->isoFormat('D [de] MMMM [de] YYYY'),'no_aplica',null),200,['Content-Type'=>'text/html; charset=UTF-8']);
    }
    public function desde_renovacion(Renovacion $renovacion): Response {
        $renovacion->load(['empleado','dispositivoNuevo','dispositivoActual']);
        return response($this->buildHtml($renovacion->empleado,$renovacion->dispositivoNuevo,$renovacion->numero_solicitud,$renovacion->fecha_entrega?->isoFormat('D [de] MMMM [de] YYYY')??now()->isoFormat('D [de] MMMM [de] YYYY'),$renovacion->destino_equipo_anterior??'no_aplica',$renovacion->precio_compra_empleado),200,['Content-Type'=>'text/html; charset=UTF-8']);
    }
    private function buildHtml(mixed $emp,mixed $disp,string $num,string $fecha,string $destino,mixed $precio): string {
        $hoy=now()->locale('es')->isoFormat('dddd, D [de] MMMM [de] YYYY');
        $empresa=Configuracion::get('nombre_empresa','Gas Zeta, S.A.');
        $dept=Configuracion::get('departamento_sistemas','Direccion de Sistemas');
        $meses=$disp?->meses_renovacion??Configuracion::cicloRenovacionMeses();
        $nombre=$emp?->nombre_completo??'___________________________';
        $cargo=$emp?->cargo??'___________________________';
        $depto=$emp?->departamento??'___________________________';
        $marca=$disp?->marca??'___________';$modelo=$disp?->modelo??'___________';
        $serie=$disp?->numero_serie??'___________';$imei=$disp?->imei??'___________';
        $color=$disp?->color??'___________';$operadora=$disp?->operadora??'___________';
        $numTel=$disp?->numero_telefonico??'___________';
        $costo=$disp?->costo?'Q '.number_format($disp->costo,2):'___________';
        $chkD=$destino==='devuelto'?'&#10003;':'&nbsp;';
        $chkC=$destino==='comprado'?'&#10003;':'&nbsp;';
        $chkN=$destino==='no_aplica'?'&#10003;':'&nbsp;';
        $precioStr=($destino==='comprado'&&$precio)?'&mdash; Q '.number_format($precio,2):'';
        return "<!DOCTYPE html><html lang='es'><head><meta charset='UTF-8'><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:10.5pt;color:#1a1a2e}.page{width:21.59cm;min-height:27.94cm;margin:0 auto;padding:1.2cm 1.8cm}.no-print{text-align:right;margin-bottom:10px}.no-print button{background:#1a3a6b;color:#fff;border:none;padding:7px 18px;border-radius:4px;cursor:pointer}.header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #1a3a6b;padding-bottom:8px;margin-bottom:12px}.logo-box{width:60px;height:60px;border:3px solid #1a3a6b;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:24pt;font-weight:900;color:#1a3a6b}.doc-title{text-align:center;font-size:12pt;font-weight:700;color:#1a3a6b;text-transform:uppercase;margin:10px 0 12px;border:2px solid #1a3a6b;padding:6px}.intro{text-align:justify;line-height:1.55;margin-bottom:10px;font-size:10pt}table.equipo{width:100%;border-collapse:collapse;margin-bottom:10px}table.equipo th{background:#1a3a6b;color:#fff;padding:6px 8px;font-size:9.5pt}table.equipo td{border:1px solid #aaa;padding:5px 8px;font-size:9.5pt}table.equipo td.lbl{background:#e8f0fb;font-weight:700;width:30%}.destino-box{border:1.5px solid #1a3a6b;border-radius:4px;padding:8px 12px;margin-bottom:10px;background:#f4f8ff}.chk-item{display:inline-flex;align-items:center;gap:5px;font-size:9.5pt;margin-right:20px}.chk{width:13px;height:13px;border:1.5px solid #333;display:inline-flex;align-items:center;justify-content:center}.conditions ol{padding-left:18px;margin-top:5px}.conditions li{line-height:1.55;margin-bottom:5px;font-size:10pt}.sig-section{margin-top:24px;text-align:center}.sig-line{border-top:1.5px solid #000;width:55%;margin:0 auto 5px}.footer{margin-top:14px;border-top:1px solid #ccc;padding-top:5px;font-size:7.5pt;color:#888;text-align:center}@media print{.no-print{display:none}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class='page'><div class='no-print'><button onclick='window.print()'>Imprimir / Guardar PDF</button></div><div class='header'><div style='display:flex;align-items:center;gap:10px'><div class='logo-box'>Z</div><div><p style='font-size:9pt;color:#666'>Ref:</p><strong style='font-size:11pt;color:#1a3a6b'>{$num}</strong></div></div><div style='text-align:right'><div style='font-size:15pt;font-weight:900;color:#1a3a6b'>{$empresa}</div><div style='font-size:11pt;font-weight:700;color:#1a3a6b'>{$dept}</div><div style='font-size:8.5pt;color:#444'>{$hoy}</div><div style='font-size:8.5pt;color:#c00'><strong>Formato: DSI-FR-012</strong></div></div></div><div class='doc-title'>Carta Custodia de Responsabilidad y Entrega de Equipo</div><p class='intro'>Por medio de la presente yo <strong>{$nombre}</strong>, con cargo de <strong>{$cargo}</strong>, perteneciente al departamento de <strong>{$depto}</strong>, empleado de <strong>{$empresa}</strong>, me comprometo a cuidar el equipo entregado. Vida util aproximada: <strong>{$meses} meses</strong>.</p><table class='equipo'><tr><th colspan='4'>DATOS DEL DISPOSITIVO</th></tr><tr><td class='lbl'>Marca</td><td>{$marca}</td><td class='lbl'>Modelo</td><td>{$modelo}</td></tr><tr><td class='lbl'>N Serie</td><td>{$serie}</td><td class='lbl'>IMEI</td><td>{$imei}</td></tr><tr><td class='lbl'>Color</td><td>{$color}</td><td class='lbl'>Operadora</td><td>{$operadora}</td></tr><tr><td class='lbl'>N Telefonico</td><td>{$numTel}</td><td class='lbl'>Costo Referencial</td><td>{$costo}</td></tr><tr><td class='lbl'>Fecha de Entrega</td><td colspan='3'>{$fecha}</td></tr></table><div class='destino-box'><strong style='color:#1a3a6b;font-size:9.5pt;display:block;margin-bottom:6px'>Equipo anterior:</strong><span class='chk-item'><span class='chk'>{$chkD}</span> Devuelto al Dpto.</span><span class='chk-item'><span class='chk'>{$chkC}</span> Comprado por empleado {$precioStr}</span><span class='chk-item'><span class='chk'>{$chkN}</span> No aplica</span></div><div class='conditions'><p style='font-size:10pt;margin-bottom:7px'>El usuario declara que el equipo se entrega en buen estado:</p><ol><li>Si el usuario pierde, maltrata o dana el equipo sera responsable de reponerlo al 100%.</li><li>El pago de equipos danados sera descontado del sueldo.</li><li>En caso de robo, informar por escrito al Jefe inmediato y al Dpto. de Sistemas con copia de la denuncia.</li></ol></div><div class='sig-section'><p style='margin-bottom:36px;font-weight:700'>Firma de Conformidad y Responsabilidad</p><div class='sig-line'></div><div style='font-weight:700;font-size:10.5pt'>{$nombre}</div><div style='font-size:8.5pt;color:#555'>{$cargo} &mdash; {$depto}</div></div><div class='footer'>GestiCell &middot; {$num} &middot; {$empresa} &mdash; {$dept}</div></div></body></html>";
    }
}